     1→/**
     2→ * Recorder Store
     3→ * Manages recording state, capture configuration, and session data
     4→ */
     5→
     6→import { create } from 'zustand';
     7→import { subscribeWithSelector } from 'zustand/middleware';
     8→import type {
     9→  CaptureRegion,
    10→  CaptureOptions,
    11→  CaptureState,
    12→  CaptureSession,
    13→  DisplayInfo,
    14→  WindowInfo,
    15→  CaptureMode,
    16→} from '../api/types';
    17→
    18→interface RecorderState {
    19→  // Recording state
    20→  captureState: CaptureState;
    21→  currentSession: CaptureSession | null;
    22→  isPaused: boolean;
    23→
    24→  // Capture configuration
    25→  captureMode: CaptureMode;
    26→  selectedRegion: CaptureRegion | null;
    27→  selectedDisplayId: string | null;
    28→  selectedWindowId: string | null;
    29→  frameRate: number;
    30→  captureMouseCursor: boolean;
    31→  captureMouseClicks: boolean;
    32→  maxDuration: number | null; // seconds
    33→  maxFrames: number | null;
    34→
    35→  // Available sources
    36→  availableDisplays: DisplayInfo[];
    37→  availableWindows: WindowInfo[];
    38→
    39→  // Stats during recording
    40→  frameCount: number;
    41→  recordingDuration: number; // milliseconds
    42→  estimatedFileSize: number; // bytes
    43→
    44→  // UI state
    45→  isSelectingRegion: boolean;
    46→  showPreview: boolean;
    47→  previewScale: number;
    48→
    49→  // Error state
    50→  error: string | null;
    51→}
    52→
    53→interface RecorderActions {
    54→  // State setters
    55→  setCaptureState: (state: CaptureState) => void;
    56→  setCurrentSession: (session: CaptureSession | null) => void;
    57→  setIsPaused: (paused: boolean) => void;
    58→
    59→  // Configuration setters
    60→  setCaptureMode: (mode: CaptureMode) => void;
    61→  setSelectedRegion: (region: CaptureRegion | null) => void;
    62→  setSelectedDisplayId: (displayId: string | null) => void;
    63→  setSelectedWindowId: (windowId: string | null) => void;
    64→  setFrameRate: (rate: number) => void;
    65→  setCaptureMouseCursor: (capture: boolean) => void;
    66→  setCaptureMouseClicks: (capture: boolean) => void;
    67→  setMaxDuration: (duration: number | null) => void;
    68→  setMaxFrames: (frames: number | null) => void;
    69→
    70→  // Source management
    71→  setAvailableDisplays: (displays: DisplayInfo[]) => void;
    72→  setAvailableWindows: (windows: WindowInfo[]) => void;
    73→  refreshSources: () => void;
    74→
    75→  // Stats updates
    76→  incrementFrameCount: () => void;
    77→  setFrameCount: (count: number) => void;
    78→  setRecordingDuration: (duration: number) => void;
    79→  setEstimatedFileSize: (size: number) => void;
    80→
    81→  // UI state
    82→  setIsSelectingRegion: (selecting: boolean) => void;
    83→  setShowPreview: (show: boolean) => void;
    84→  setPreviewScale: (scale: number) => void;
    85→
    86→  // Error handling
    87→  setError: (error: string | null) => void;
    88→  clearError: () => void;
    89→
    90→  // Computed getters
    91→  getCaptureOptions: () => CaptureOptions;
    92→  canStartRecording: () => boolean;
    93→
    94→  // Reset
    95→  reset: () => void;
    96→  resetSession: () => void;
    97→}
    98→
    99→const initialState: RecorderState = {
   100→  captureState: 'idle',
   101→  currentSession: null,
   102→  isPaused: false,
   103→  captureMode: 'region',
   104→  selectedRegion: null,
   105→  selectedDisplayId: null,
   106→  selectedWindowId: null,
   107→  frameRate: 15,
   108→  captureMouseCursor: true,
   109→  captureMouseClicks: false,
   110→  maxDuration: null,
   111→  maxFrames: null,
   112→  availableDisplays: [],
   113→  availableWindows: [],
   114→  frameCount: 0,
   115→  recordingDuration: 0,
   116→  estimatedFileSize: 0,
   117→  isSelectingRegion: false,
   118→  showPreview: true,
   119→  previewScale: 1,
   120→  error: null,
   121→};
   122→
   123→export const useRecorderStore = create<RecorderState & RecorderActions>()(
   124→  subscribeWithSelector((set, get) => ({
   125→    ...initialState,
   126→
   127→    // State setters
   128→    setCaptureState: (captureState) => set({ captureState }),
   129→    setCurrentSession: (currentSession) => set({ currentSession }),
   130→    setIsPaused: (isPaused) => set({ isPaused }),
   131→
   132→    // Configuration setters
   133→    setCaptureMode: (captureMode) => set({ captureMode }),
   134→    setSelectedRegion: (selectedRegion) => set({ selectedRegion }),
   135→    setSelectedDisplayId: (selectedDisplayId) => set({ selectedDisplayId }),
   136→    setSelectedWindowId: (selectedWindowId) => set({ selectedWindowId }),
   137→    setFrameRate: (frameRate) => set({ frameRate: Math.min(Math.max(frameRate, 1), 60) }),
   138→    setCaptureMouseCursor: (captureMouseCursor) => set({ captureMouseCursor }),
   139→    setCaptureMouseClicks: (captureMouseClicks) => set({ captureMouseClicks }),
   140→    setMaxDuration: (maxDuration) => set({ maxDuration }),
   141→    setMaxFrames: (maxFrames) => set({ maxFrames }),
   142→
   143→    // Source management
   144→    setAvailableDisplays: (availableDisplays) => set({ availableDisplays }),
   145→    setAvailableWindows: (availableWindows) => set({ availableWindows }),
   146→    refreshSources: () => {
   147→      // This will be called by components that have access to the API
   148→      // The actual fetching happens in the component/service layer
   149→    },
   150→
   151→    // Stats updates
   152→    incrementFrameCount: () => set((state) => ({ frameCount: state.frameCount + 1 })),
   153→    setFrameCount: (frameCount) => set({ frameCount }),
   154→    setRecordingDuration: (recordingDuration) => set({ recordingDuration }),
   155→    setEstimatedFileSize: (estimatedFileSize) => set({ estimatedFileSize }),
   156→
   157→    // UI state
   158→    setIsSelectingRegion: (isSelectingRegion) => set({ isSelectingRegion }),
   159→    setShowPreview: (showPreview) => set({ showPreview }),
   160→    setPreviewScale: (previewScale) => set({ previewScale }),
   161→
   162→    // Error handling
   163→    setError: (error) => set({ error }),
   164→    clearError: () => set({ error: null }),
   165→
   166→    // Computed getters
   167→    getCaptureOptions: (): CaptureOptions => {
   168→      const state = get();
   169→      return {
   170→        mode: state.captureMode,
   171→        region: state.selectedRegion ?? undefined,
   172→        displayId: state.selectedDisplayId ?? undefined,
   173→        windowId: state.selectedWindowId ?? undefined,
   174→        frameRate: state.frameRate,
   175→        captureMouseCursor: state.captureMouseCursor,
   176→        captureMouseClicks: state.captureMouseClicks,
   177→        maxDuration: state.maxDuration ?? undefined,
   178→        maxFrames: state.maxFrames ?? undefined,
   179→      };
   180→    },
   181→
   182→    canStartRecording: (): boolean => {
   183→      const state = get();
   184→      if (state.captureState !== 'idle') return false;
   185→
   186→      switch (state.captureMode) {
   187→        case 'region':
   188→          return state.selectedRegion !== null;
   189→        case 'screen':
   190→          return state.selectedDisplayId !== null;
   191→        case 'window':
   192→          return state.selectedWindowId !== null;
   193→        case 'webcam':
   194→        case 'board':
   195→          return true;
   196→        default:
   197→          return false;
   198→      }
   199→    },
   200→
   201→    // Reset
   202→    reset: () => set(initialState),
   203→    resetSession: () =>
   204→      set({
   205→        currentSession: null,
   206→        frameCount: 0,
   207→        recordingDuration: 0,
