     3→export type ButtonVariant = 'primary' | 'secondary' | 'ghost' | 'danger';
     4→export type ButtonSize = 'sm' | 'md' | 'lg';
     5→
     6→export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
     7→  variant?: ButtonVariant;
