     9→  isLoading?: boolean;
    10→  leftIcon?: ReactNode;
    11→  rightIcon?: ReactNode;
    12→  fullWidth?: boolean;
    13→}
    14→
    15→const variantStyles: Record<ButtonVariant, string> = {
    16→  primary:
    17→    'bg-primary-600 text-white hover:bg-primary-500 active:bg-primary-700 disabled:bg-surface-600',
    18→  secondary:
    19→    'bg-surface-700 text-surface-100 hover:bg-surface-600 active:bg-surface-800 disabled:bg-surface-700 border border-surface-600',
    20→  ghost:
    21→    'bg-transparent text-surface-300 hover:bg-surface-700 hover:text-surface-100 active:bg-surface-600 disabled:bg-transparent',
    22→  danger:
    23→    'bg-accent-error text-white hover:bg-accent-error-light active:bg-accent-error-dark disabled:bg-surface-600',
    24→};
    25→
    26→const sizeStyles: Record<ButtonSize, string> = {
    27→  sm: 'h-8 px-3 text-xs gap-1.5',
    28→  md: 'h-10 px-4 text-sm gap-2',
    29→  lg: 'h-12 px-6 text-base gap-2.5',
    30→};
    31→
    32→const iconSizeStyles: Record<ButtonSize, string> = {
    33→  sm: 'w-3.5 h-3.5',
    34→  md: 'w-4 h-4',
    35→  lg: 'w-5 h-5',
    36→};
    37→
    38→export const Button = forwardRef<HTMLButtonElement, ButtonProps>(
    39→  (
    40→    {
    41→      variant = 'primary',
    42→      size = 'md',
    43→      isLoading = false,
    44→      leftIcon,
    45→      rightIcon,
    46→      fullWidth = false,
    47→      disabled,
    48→      className = '',
    49→      children,
    50→      ...props
    51→    },
    52→    ref
    53→  ) => {
    54→    const isDisabled = disabled || isLoading;
    55→
    56→    return (
    57→      <button
