    60→        className={`
    61→          inline-flex items-center justify-center
    62→          font-medium rounded-lg
    63→          transition-colors duration-200
    64→          focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary-500 focus-visible:ring-offset-2 focus-visible:ring-offset-surface-900
    65→          disabled:opacity-50 disabled:cursor-not-allowed
    66→          ${variantStyles[variant]}
    67→          ${sizeStyles[size]}
    68→          ${fullWidth ? 'w-full' : ''}
    69→          ${className}
    70→        `.trim()}
    71→        {...props}
    72→      >
    73→        {isLoading ? (
    74→          <svg
    75→            className={`animate-spin ${iconSizeStyles[size]}`}
    76→            xmlns="http://www.w3.org/2000/svg"
    77→            fill="none"
    78→            viewBox="0 0 24 24"
    79→          >
    80→            <circle
    81→              className="opacity-25"
    82→              cx="12"
    83→              cy="12"
    84→              r="10"
    85→              stroke="currentColor"
    86→              strokeWidth="4"
    87→            />
    88→            <path
    89→              className="opacity-75"
    90→              fill="currentColor"
    91→              d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
    92→            />
    93→          </svg>
    94→        ) : (
    95→          <>
    96→            {leftIcon && (
    97→              <span className={`flex-shrink-0 ${iconSizeStyles[size]}`}>
    98→                {leftIcon}
    99→              </span>
   100→            )}
   101→            {children}
   102→            {rightIcon && (
   103→              <span className={`flex-shrink-0 ${iconSizeStyles[size]}`}>
   104→                {rightIcon}
   105→              </span>
   106→            )}
   107→          </>
   108→        )}
   109→      </button>
   110→    );
   111→  }
   112→);
