     1→import { useEffect, useRef } from 'react';
     2→
     3→export type KeyModifiers = {
     4→  ctrl?: boolean;
     5→  alt?: boolean;
     6→  shift?: boolean;
     7→  meta?: boolean;
     8→};
     9→
    10→export interface HotkeyConfig {
    11→  key: string;
    12→  modifiers?: KeyModifiers;
    13→  callback: (event: KeyboardEvent) => void;
    14→  enabled?: boolean;
    15→  preventDefault?: boolean;
    16→  stopPropagation?: boolean;
    17→  description?: string;
    18→}
    19→
    20→export interface UseHotkeysOptions {
    21→  enableOnInput?: boolean;
    22→  enableOnContentEditable?: boolean;
    23→}
    24→
    25→function matchesModifiers(event: KeyboardEvent, modifiers?: KeyModifiers): boolean {
    26→  const { ctrl = false, alt = false, shift = false, meta = false } = modifiers || {};
    27→  return (
    28→    event.ctrlKey === ctrl &&
    29→    event.altKey === alt &&
    30→    event.shiftKey === shift &&
    31→    event.metaKey === meta
    32→  );
    33→}
    34→
    35→function isInputElement(element: EventTarget | null): boolean {
    36→  if (!element || !(element instanceof HTMLElement)) return false;
    37→  const tagName = element.tagName.toLowerCase();
    38→  return (
    39→    tagName === 'input' ||
    40→    tagName === 'textarea' ||
    41→    tagName === 'select' ||
    42→    element.isContentEditable
    43→  );
    44→}
    45→
    46→export function useHotkeys(
    47→  hotkeys: HotkeyConfig[],
    48→  options: UseHotkeysOptions = {}
    49→): void {
    50→  const { enableOnInput = false, enableOnContentEditable = false } = options;
    51→  const hotkeysRef = useRef(hotkeys);
    52→  hotkeysRef.current = hotkeys;
    53→
    54→  useEffect(() => {
    55→    const handleKeyDown = (event: KeyboardEvent) => {
    56→      // Check if focus is on an input element
    57→      if (!enableOnInput && isInputElement(event.target)) {
    58→        if (!enableOnContentEditable && (event.target as HTMLElement).isContentEditable) {
    59→          return;
    60→        }
    61→        return;
    62→      }
    63→
