    19→  sm: 'w-3 h-3',
    20→  md: 'w-5 h-5',
    21→  lg: 'w-6 h-6',
    22→};
    23→
    24→const thumbTranslateStyles: Record<ToggleSize, string> = {
    25→  sm: 'translate-x-4',
    26→  md: 'translate-x-5',
    27→  lg: 'translate-x-7',
    28→};
    29→
    30→export const Toggle = forwardRef<HTMLInputElement, ToggleProps>(
    31→  (
    32→    {
    33→      size = 'md',
    34→      label,
    35→      description,
    36→      labelPosition = 'right',
    37→      disabled,
    38→      className = '',
    39→      checked,
    40→      id,
    41→      ...props
    42→    },
    43→    ref
    44→  ) => {
    45→    const inputId = id || `toggle-${Math.random().toString(36).slice(2, 9)}`;
    46→
    47→    const toggle = (
    48→      <label
    49→        htmlFor={inputId}
    50→        className={`
    51→          relative inline-flex items-center cursor-pointer
    52→          ${disabled ? 'opacity-50 cursor-not-allowed' : ''}
    53→        `}
    54→      >
    55→        <input
    56→          ref={ref}
    57→          id={inputId}
    58→          type="checkbox"
    59→          checked={checked}
    60→          disabled={disabled}
    61→          className="sr-only peer"
    62→          {...props}
    63→        />
    64→        <div
    65→          className={`
    66→            ${trackSizeStyles[size]}
    67→            bg-surface-600 rounded-full
    68→            peer-focus-visible:ring-2 peer-focus-visible:ring-primary-500/50
    69→            peer-checked:bg-primary-600
    70→            transition-colors duration-200
    71→          `}
    72→        />
    73→        <div
    74→          className={`
    75→            ${thumbSizeStyles[size]}
    76→            absolute left-0.5 top-1/2 -translate-y-1/2
    77→            bg-white rounded-full shadow-md
    78→            transition-transform duration-200
    79→            peer-checked:${thumbTranslateStyles[size]}
    80→          `}
    81→        />
    82→      </label>
    83→    );
