     2→ * RecorderPage Component
     3→ * Full recorder page with region selection, recording controls, and keyboard shortcuts
     4→ */
     5→
     6→import { useState, useCallback, useMemo } from 'react';
     7→import { useRecorderStore } from '../../../stores/recorderStore';
     8→import { useHotkeys } from '../../../hooks/useHotkeys';
     9→import { Icon } from '../../../components/atoms/Icon';
    10→import { Button } from '../../../components/atoms/Button';
    11→import { Slider } from '../../../components/atoms/Slider';
    12→import { Toggle } from '../../../components/atoms/Toggle';
    13→import { Tooltip } from '../../../components/molecules/Tooltip';
    14→import { StatusBar, type StatusType } from '../../../components/organisms/StatusBar';
    15→import { RegionSelector } from '../components/RegionSelector';
    16→import { RecordingControls } from '../components/RecordingControls';
    17→import { RecordingTimer } from '../components/RecordingTimer';
    18→import { CaptureSourceSelector } from '../components/CaptureSourceSelector';
    19→import { WebcamPreview } from '../components/WebcamPreview';
    20→import { useCapture } from '../hooks/useCapture';
    21→import { useWebcam } from '../hooks/useWebcam';
    22→
    23→export interface RecorderPageProps {
    24→  onClose?: () => void;
    25→  onRecordingComplete?: (frameCount: number, duration: number) => void;
    26→  className?: string;
    27→}
    28→
    29→export function RecorderPage({
    30→  onClose,
    31→  onRecordingComplete,
    32→  className = '',
    33→}: RecorderPageProps) {
    34→  const [showSettings, setShowSettings] = useState(false);
    35→  const [showWebcam, setShowWebcam] = useState(false);
    36→  const [webcamPosition, setWebcamPosition] = useState<'top-left' | 'top-right' | 'bottom-left' | 'bottom-right'>('bottom-right');
    37→  const [webcamSize, setWebcamSize] = useState<'small' | 'medium' | 'large'>('medium');
    38→
    39→  // Store state
    40→  const {
    41→    captureMode,
    42→    selectedRegion,
    43→    selectedDisplayId,
    44→    selectedWindowId,
    45→    frameRate,
    46→    captureMouseCursor,
    47→    captureMouseClicks,
    48→    availableDisplays,
    49→    availableWindows,
    50→    frameCount,
    51→    recordingDuration,
    52→    error,
    53→    setCaptureMode,
    54→    setSelectedRegion,
    55→    setSelectedDisplayId,
    56→    setSelectedWindowId,
    57→    setFrameRate,
    58→    setCaptureMouseCursor,
    59→    setCaptureMouseClicks,
    60→    clearError,
    61→  } = useRecorderStore();
    62→
    63→  // Capture hook
    64→  const {
    65→    captureState,
    66→    isPaused,
    67→    canStart,
    68→    start,
    69→    stop,
    70→    togglePause,
    71→    discard,
    72→    refreshSources,
    73→  } = useCapture({
    74→    onStop: (frames, duration) => {
    75→      onRecordingComplete?.(frames, duration);
    76→    },
    77→    onError: (err) => {
    78→      console.error('Capture error:', err);
    79→    },
    80→  });
    81→
    82→  // Webcam hook
    83→  const webcam = useWebcam({
    84→    onError: (err) => {
    85→      console.error('Webcam error:', err);
    86→    },
    87→  });
    88→
    89→  // Computed states
    90→  const isRecording = captureState === 'recording' || captureState === 'paused';
    91→  const isIdle = captureState === 'idle';
    92→  const isStarting = captureState === 'starting';
    93→  const isStopping = captureState === 'stopping';
    94→
    95→  // Status bar configuration
    96→  const status: StatusType = isRecording
    97→    ? isPaused
    98→      ? 'warning'
    99→      : 'recording'
   100→    : isStarting || isStopping
   101→      ? 'loading'
   102→      : error
   103→        ? 'error'
   104→        : 'idle';
   105→
   106→  const statusMessage = isRecording
   107→    ? isPaused
   108→      ? 'Paused'
   109→      : 'Recording'
   110→    : isStarting
   111→      ? 'Starting...'
   112→      : isStopping
   113→        ? 'Stopping...'
   114→        : error
   115→          ? error
   116→          : 'Ready';
   117→
   118→  // Keyboard shortcuts
   119→  const handleRecordHotkey = useCallback(() => {
   120→    if (isIdle && canStart) {
   121→      start();
   122→    } else if (isRecording) {
   123→      togglePause();
   124→    }
   125→  }, [isIdle, isRecording, canStart, start, togglePause]);
   126→
   127→  const handleStopHotkey = useCallback(() => {
   128→    if (isRecording) {
   129→      stop();
   130→    }
   131→  }, [isRecording, stop]);
   132→
   133→  const handleDiscardHotkey = useCallback(() => {
   134→    if (isRecording) {
   135→      discard();
   136→    }
   137→  }, [isRecording, discard]);
   138→
   139→  const hotkeys = useMemo(
   140→    () => [
   141→      {
   142→        key: 'F7',
   143→        callback: handleRecordHotkey,
   144→        description: 'Start/Pause Recording',
   145→      },
   146→      {
   147→        key: 'F8',
   148→        callback: handleStopHotkey,
   149→        description: 'Stop Recording',
   150→      },
   151→      {
   152→        key: 'F9',
   153→        callback: handleDiscardHotkey,
   154→        description: 'Discard Recording',
   155→      },
   156→      {
   157→        key: 'Escape',
   158→        callback: () => {
   159→          if (showSettings) {
   160→            setShowSettings(false);
   161→          } else if (!isRecording && onClose) {
   162→            onClose();
   163→          }
   164→        },
   165→        description: 'Close/Cancel',
